export enum StockState {
    Empty = 0,
    Available = 1,
    Reserved = 2
}

export abstract class StockItem {
    constructor(private readonly sku: string, protected quantity: number) {}

    get code(): string { return this.sku; }
    get count(): number { return this.quantity; }
    set count(value: number) { this.quantity = value; }

    abstract price(): number;
}

export class Product extends StockItem {
    constructor(sku: string, quantity: number, private readonly unitPrice: number) {
        super(sku, quantity);
    }

    override price(): number { return this.unitPrice * this.count; }
}

export namespace Product {
    export function create(sku: string): Product { return new Product(sku, 0, 0); }
}

import { Product, StockState } from "./domain";

export class Warehouse implements AuditRecord {
    constructor(public readonly warehouse: string, public readonly product: Product) {}

    get stockCount(): number { return this.product.count; }
    get state(): StockState {
        if (this.stockCount === 0) return StockState.Empty;
        return StockState.Available;
    }
}

import { Product, StockItem, StockState } from "./domain";
import { Warehouse } from "./warehouse";

const item = new Product("BK-001", 3, 12);
const warehouse = new Warehouse("north", item);
const record: AuditRecord = warehouse;
const stock: StockItem = item;
const empty = Product.create("BK-002");

export const inventoryValue: number = stock.price();
export const counted: number = record.stockCount + empty.count;
export const state: StockState = warehouse.state;

